import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';

const harness = resolve('tests/browser/reviewer-chat-store-acceptance.mjs');
const testPath = resolve('tests/browser/reviewer-chat-organization-boundary.test.mjs');
const harnessBefore = await readFile(harness, 'utf8');
const testBefore = await readFile(testPath, 'utf8');
const sha256 = (value) => createHash('sha256').update(value).digest('hex');
const scratch = await mkdtemp(join(tmpdir(), 'd191-red-proof-'));
const observations = [];
try {
  const importNeedle = "new URL('./reviewer-chat-store-acceptance.mjs', import.meta.url)";
  assert.equal(testBefore.split(importNeedle).length, 2);
  const template = testBefore
    .replace('const source = await readFile(', 'let source = await readFile(')
    .replace(importNeedle, `new URL(${JSON.stringify(pathToFileURL(harness).href)})`);
  const marker = '// Run the actual default-lane prerequisite';
  assert.equal(template.split(marker).length, 2);
  const mutations = [
    {
      name: 'old-device-gate',
      injection: `source = source.replace("        stage = 'open_chat';", "        assert.equal(storageShape.activeOrganizationPresent, true, 'selected organization must persist as a valid object');\\n        stage = 'open_chat';");\n`,
      expected_failure: 'selected organization must persist as a valid object',
    },
    {
      name: 'no-op-transport-verdict',
      injection: `{
        const start = source.indexOf('        const network = memberTransport.snapshot();');
        const end = source.indexOf('        report.screenshots.result', start);
        assert.ok(start > 0 && end > start);
        source = source.slice(0, start) + '        const network = memberTransport.snapshot();\\n' + source.slice(end);
      }\n`,
      expected_failure: 'Missing expected exception.',
    },
  ];
  for (const mutation of mutations) {
    const scratchTest = join(scratch, `${mutation.name}.test.mjs`);
    await writeFile(scratchTest, template.replace(marker, mutation.injection + marker));
    const child = spawnSync(process.execPath, ['--test', scratchTest], { encoding: 'utf8' });
    const output = child.stdout + child.stderr;
    assert.equal(child.status, 1, `${mutation.name} must fail the existing source guard`);
    assert.ok(output.includes('ERR_ASSERTION'), `${mutation.name} must fail by assertion`);
    assert.ok(output.includes(mutation.expected_failure), `${mutation.name} must hit the intended assertion`);
    observations.push({
      mutation: mutation.name,
      invocation: [process.execPath, '--test', '<scratch>/' + mutation.name + '.test.mjs'],
      expected_exit_code: 1,
      actual_exit_code: child.status,
      expected_failure_code: 'ERR_ASSERTION',
      expected_failure_message: mutation.expected_failure,
      output: output.replaceAll(scratch, '<scratch>'),
    });
  }
  assert.equal(await readFile(harness, 'utf8'), harnessBefore, 'real harness must remain unchanged');
  assert.equal(await readFile(testPath, 'utf8'), testBefore, 'real source guard must remain unchanged');
  console.log(JSON.stringify({
    schema_version: 1,
    scope: 'Source guard mutation proof only; zero browser/product behavior credit',
    verdict: 'both_mutants_rejected',
    shared_source_unchanged: true,
    harness_sha256: sha256(harnessBefore),
    source_guard_sha256: sha256(testBefore),
    observations,
  }, null, 2));
} finally {
  await rm(scratch, { recursive: true, force: true });
}
